import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [amount, setAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [totalRaised, setTotalRaised] = useState(0);
  const [error, setError] = useState(null);
  const [isAnimating, setIsAnimating] = useState(false);
  const [topDonors, setTopDonors] = useState([]);
  const [recentDonations, setRecentDonations] = useState([]);
  const goal = 450000;
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  // ... (keep all existing functions like loadScript, handleAmountChange, triggerConfetti)

  const handlePayment = async () => {
    setLoading(true);
    setError(null);
    setIsAnimating(true);

    if (amount === '' || parseInt(amount) < 1) {
      setError('Please enter an amount of at least ₹1');
      setLoading(false);
      setIsAnimating(false);
      return;
    }

    try {
      const res = await loadScript('https://checkout.razorpay.com/v1/checkout.js');
      if (!res) {
        setError('Razorpay SDK failed to load. Are you online?');
        return;
      }

      const orderResponse = await axios.post(`${API_URL}/create-order`, {
        amount: parseInt(amount)
      });

      const { id: order_id, amount: order_amount } = orderResponse.data;

      const options = {
        key: process.env.REACT_APP_RAZORPAY_KEY_ID,
        amount: order_amount.toString(),
        currency: 'INR',
        name: 'GT Bike Fundraiser',
        description: 'Donation for GT Bike',
        order_id: order_id,
        handler: async function (response) {
          try {
            await axios.post(`${API_URL}/save-donation`, {
              amount: parseInt(amount),
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_order_id: response.razorpay_order_id
            });
            setIsAnimating(false);
            triggerConfetti();
            fetchDonations(); // Fetch updated donations after successful payment
            setAmount('');
          } catch (error) {
            console.error('Error saving donation:', error);
          }
        },
        theme: {
          color: '#FF6B00',
        },
        modal: {
          ondismiss: function() {
            setIsAnimating(false);
            setLoading(false);
          }
        }
      };

      const paymentObject = new window.Razorpay(options);
      paymentObject.open();
    } catch (error) {
      console.error('Payment error:', error);
      setError(error.response?.data?.error || 'Error processing payment. Please try again.');
      setIsAnimating(false);
    } finally {
      setLoading(false);
    }
  };

  const fetchDonations = async () => {
    try {
      const response = await axios.get(`${API_URL}/get-donations`);
      setTotalRaised(response.data.total_raised || 0);
      setTopDonors(response.data.top_donors || []);
      setRecentDonations(response.data.recent_donations || []);
    } catch (error) {
      console.error('Error fetching donations:', error);
      setError('Failed to fetch donation data');
    }
  };

  useEffect(() => {
    fetchDonations();
  }, []);

  return (
    <div className={`app ${isAnimating ? 'pulse-effect' : ''}`}>
      <div className="bike-background"></div>
      <div className="gradient-overlay"></div>

      <header className="header">
        <h1>Help Me Ride My Dream <span className="gt-text">GT650 Bike</span></h1>
        <p className="tagline">Every rupee brings me closer to the open road</p>
      </header>

      <main className="main-content">
        <div className="donation-card">
          <div className="progress-container">
            <h3>Fundraising Progress</h3>
            <div className="progress-bar">
              <div
                className="progress-fill"
                style={{ width: `${Math.min(Math.round((totalRaised / goal) * 100), 100)}%` }}
              ></div>
            </div>
            <div className="progress-text">
              <span>₹{totalRaised.toLocaleString()} raised</span>
              <span>Goal: ₹{goal.toLocaleString()}</span>
            </div>
            <div className="progress-percentage">
              {Math.round((totalRaised / goal) * 100)}% Complete
            </div>
          </div>

          <div className="donation-form">
            <h2>Fuel My Adventure</h2>
            <div className="form-group">
              <label htmlFor="amount">Your Contribution (₹)</label>
              <input
                id="amount"
                type="number"
                min="1"
                value={amount}
                onChange={handleAmountChange}
                placeholder="Enter amount (min ₹1)"
              />
            </div>

            {error && <div className="error-message">{error}</div>}

            <button 
              onClick={handlePayment} 
              disabled={loading || amount === '' || parseInt(amount) < 1}
              className={`donate-button ${loading ? 'loading' : ''}`}
            >
              {loading ? (
                <span className="button-text">Processing...</span>
              ) : (
                <>
                  <span className="button-text">Donate Now</span>
                  <span className="button-icon">🚴‍♂️</span>
                </>
              )}
            </button>
          </div>

          {/* Donors Sections */}
          <div className="donors-sections">
            <div className="donors-column">
              <h3>Top Donors</h3>
              {topDonors.length > 0 ? (
                <ol className="donors-list">
                  {topDonors.map((donor, index) => (
                    <li key={index}>
                      <span className="donor-name">{donor.name || 'Anonymous'}</span>
                      <span className="donor-amount">₹{donor.amount.toLocaleString()}</span>
                    </li>
                  ))}
                </ol>
              ) : (
                <p className="no-donations">No donors yet</p>
              )}
            </div>

            <div className="donors-column">
              <h3>Recent Donations</h3>
              {recentDonations.length > 0 ? (
                <ul className="donors-list">
                  {recentDonations.map((donation, index) => (
                    <li key={index}>
                      <span className="donor-name">{donation.name || 'Anonymous'}</span>
                      <span className="donor-amount">₹{donation.amount.toLocaleString()}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="no-donations">No recent donations</p>
              )}
            </div>
          </div>
        </div>
      </main>

      <footer className="footer">
        <p>Thank you for supporting my passion!</p>
      </footer>
    </div>
  );
}

export default App;
